import os
from google.cloud import texttospeech

def list_voices():
    client = texttospeech.TextToSpeechClient()
    voices = client.list_voices()
    for voice in voices.voices:
        print(f"Name: {voice.name}, Language Code: {voice.language_codes[0]}")

def select_voice(language_code):
    client = texttospeech.TextToSpeechClient()
    voices = client.list_voices()
    for voice in voices.voices:
        if language_code in voice.language_codes:
            return voice.name
    return None

import os
import re

def check_safety(text):
    unsafe_patterns = [
        r'\b(hate|violence|discrimination)\b',
        r'\b(kill|murder|assault)\b',
        r'\b(abuse|harassment)\b',
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, text, re.IGNORECASE):
            return False
    return True

